import json
d=json.load(open('splitviews.json'))
def walk(o, out):
    if isinstance(o, dict):
        if o.get('type')=='text': out.append(o.get('text',''))
        elif o.get('type')=='codeVoice': out.append('\`'+o.get('code','')+'\`')
        elif o.get('type')=='paragraph':
            sub=[]; 
            for c in o.get('inlineContent',[]): walk(c, sub)
            out.append(''.join(sub)+'\n')
        elif o.get('type')=='heading': out.append('\n## '+o.get('text','')+'\n')
        elif o.get('type')=='unorderedList':
            for it in o.get('items',[]):
                sub=[]
                for c in it.get('content',[]): walk(c, sub)
                out.append('- '+''.join(sub))
        else:
            for k,v in o.items():
                if k in ('references','metadata','seeAlsoSections','hierarchy','identifier','variants'): continue
                walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
print(''.join(walk.__defaults__ or []) if False else '')
out=[]
walk(d.get('primaryContentSections',[]),out)
walk(d.get('abstract',[]),out)
print(''.join(out))
print('---TITLE---', d.get('metadata',{}).get('title'))
print('---PLATFORMS---', d.get('metadata',{}).get('platforms'))
